SELECT 
  COUNT(*) as total_embeddings,
  COUNT(DISTINCT type_id) as unique_notes,
  array_agg(DISTINCT type_id ORDER BY type_id) as note_ids
FROM embedding_v1
WHERE type = 'note' AND type_id >= 10001;